    let currentTab = 'year1';
    let currentTopicIndex = 0;
    let currentCardIndex = 0;

    const selectionView = document.getElementById('selection-view');
    const studyView = document.getElementById('study-view');
    const topicGrid = document.getElementById('topic-grid');
    const emptyState = document.getElementById('empty-state');
    
    const cardElement = document.getElementById('card-element');
    const frontText = document.getElementById('front-text');
    const backText = document.getElementById('back-text');
    const cardCounter = document.getElementById('card-counter');
    const prevBtn = document.getElementById('prev-btn');
    const nextBtn = document.getElementById('next-btn');
    const activeTopicName = document.getElementById('active-topic-name');

    function init() {
      const mainTabs = document.getElementById('main-tabs');
      const mobileDropdown = document.getElementById('mobile-tab-dropdown');

      // Desktop Tab Listeners
      if (mainTabs) {
        mainTabs.querySelectorAll('.tab-item').forEach(tab => {
          tab.onclick = () => {
            mainTabs.querySelectorAll('.tab-item').forEach(t => t.classList.remove('active'));
            tab.classList.add('active');
            currentTab = tab.dataset.tab;
            if (mobileDropdown) mobileDropdown.value = currentTab;
            renderTopics();
          };
        });
      }

      // Mobile Dropdown Listener
      if (mobileDropdown) {
        mobileDropdown.onchange = (e) => {
          currentTab = e.target.value;
          // Sync desktop tabs
          if (mainTabs) {
            mainTabs.querySelectorAll('.tab-item').forEach(t => {
              t.classList.toggle('active', t.dataset.tab === currentTab);
            });
          }
          renderTopics();
        };
      }

      // Card Flip
      cardElement.onclick = () => {
        cardElement.classList.toggle('is-flipped');
      };

      // Nav Buttons
      prevBtn.onclick = (e) => {
        e.stopPropagation();
        if (currentCardIndex > 0) {
          currentCardIndex--;
          updateCard();
        }
      };

      nextBtn.onclick = (e) => {
        e.stopPropagation();
        const cards = FLASH_DATA[currentTab][currentTopicIndex].cards;
        if (currentCardIndex < cards.length - 1) {
          currentCardIndex++;
          updateCard();
        }
      };

      renderTopics();
      // Also initialize icons for static elements in HTML
      lucide.createIcons();
    }

    function renderTopics() {
      try {
        const topics = FLASH_DATA[currentTab];
        topicGrid.innerHTML = '';
        
        if (topics && topics.length > 0) {
          emptyState.classList.add('hidden');
          topicGrid.classList.remove('hidden');
          
          const sectionsMap = {};
          topics.forEach(t => {
            const s = t.section || 'General';
            if (!sectionsMap[s]) sectionsMap[s] = [];
            sectionsMap[s].push(t);
          });

          for (const [sectionName, secTopics] of Object.entries(sectionsMap)) {
            if (sectionName !== 'General' || Object.keys(sectionsMap).length > 1) {
              const header = document.createElement('div');
              header.className = 'section-header';
              header.style.gridColumn = '1 / -1';
              header.textContent = sectionName;
              topicGrid.appendChild(header);
            }
            
            secTopics.forEach((t) => {
              const idx = topics.indexOf(t);
              const isFreeDemo = (idx === 0);
              const card = document.createElement('div');
              card.className = 'topic-card-item';
              card.innerHTML = `
                ${isFreeDemo ? '<div style="position:absolute; top:12px; right:12px; background:var(--accent); color:white; font-size:10px; font-weight:800; padding:3px 10px; border-radius:6px; text-transform:uppercase; letter-spacing:1px; z-index:1; box-shadow:0 4px 12px rgba(var(--accent-rgb),0.3);">Free Demo</div>' : ''}
                <div class="topic-card-icon">
                  <i data-lucide="${t.icon || 'book'}"></i>
                </div>
                <div class="topic-card-title">${t.topic || 'Untitled Topic'}</div>
                <div class="topic-card-count">${(t.cards || []).length} Cards</div>
              `;
              card.onclick = () => startStudyMode(idx, isFreeDemo);
              topicGrid.appendChild(card);
            });
          }
          
          // Initialize Lucide icons with error catching
          if (window.lucide) {
            lucide.createIcons();
          }
        } else {
          topicGrid.classList.add('hidden');
          emptyState.classList.remove('hidden');
        }
      } catch (err) {
        console.error("MediHelp FlashCards Error:", err);
        topicGrid.classList.add('hidden');
        emptyState.classList.remove('hidden');
      }
    }

    async function isPremium() {
      return await MediHelp.isPremium();
    }

    function openPremiumModal() {
      const modal = document.getElementById('premium-modal');
      if (modal) modal.classList.add('visible');
    }

    function closePremiumModal() {
      const modal = document.getElementById('premium-modal');
      if (modal) modal.classList.remove('visible');
    }

    async function verifyLicense() {
      const key = document.getElementById('license-key').value.trim();
      const email = document.getElementById('license-email').value.trim();
      
      if (!key || !email) {
        alert("Please enter both license key and email.");
        return;
      }
      
      const btn = document.querySelector('.license-entry .btn-secondary');
      if (btn) {
        btn.textContent = "Verifying...";
        btn.disabled = true;
      }

      try {
        const success = await MediHelp.License.verify(key, email);
        if (success) {
          location.reload();
        } else {
          throw new Error("Verification failed");
        }
      } catch (e) {
        console.error("License Verification Error:", e);
        let msg = "Invalid license key or email. Please check and try again.";
        if (e.message === "LICENSE_LIMIT_REACHED") msg = "License limit reached (5 devices max).";
        if (e.message === "TIMEOUT") msg = "Verification timed out. The server can take up to 90s. If a row was saved in Supabase, refresh the page in a few seconds.";
        
        alert(msg);
        if (btn) {
          btn.textContent = "Activate Access";
          btn.disabled = false;
        }
      }
    }

    async function startStudyMode(index, isFreeDemo = false) {
      if (!isFreeDemo) {
        const premium = await isPremium();
        if (!premium) {
          const { data: { user } } = await window.dbClient.auth.getUser();
          if (!user) {
            MediHelp.showAuthModal();
          } else {
            openPremiumModal();
          }
          return;
        }
      }
      currentTopicIndex = index;
      currentCardIndex = 0;
      activeTopicName.textContent = FLASH_DATA[currentTab][index].topic;
      
      selectionView.classList.add('hidden');
      studyView.classList.remove('hidden');
      updateCard();
    }

    function exitStudyMode() {
      studyView.classList.add('hidden');
      selectionView.classList.remove('hidden');
    }

    function updateCard() {
      const topics = FLASH_DATA[currentTab];
      if (!topics || !topics[currentTopicIndex]) return;

      const cards = topics[currentTopicIndex].cards;
      const card = cards[currentCardIndex];

      cardElement.classList.remove('is-flipped');
      
      setTimeout(() => {
        frontText.innerHTML = card.q;
        backText.innerHTML = card.a;
        cardCounter.textContent = `${currentCardIndex + 1} / ${cards.length}`;
        
        prevBtn.disabled = currentCardIndex === 0;
        nextBtn.disabled = currentCardIndex === cards.length - 1;
      }, 50);
    }

    init();
  